{# KSA End of Service Benefit - Print Format - Saudi Labor Law Compliant #}
{% set company_doc = frappe.get_doc('Company', doc.company) if doc.company else None %}
{% set letter_head_name = company_doc.default_letter_head if company_doc else None %}
{% set letter_head = frappe.get_doc('Letter Head', letter_head_name) if letter_head_name else None %}
{% set logo_url = letter_head.image if letter_head and letter_head.image else None %}

<style>
    .eosb-print {
        font-family: 'Helvetica Neue', Arial, Helvetica, sans-serif;
        font-size: 11px;
        color: #000;
        max-width: 780px;
        margin: 0 auto;
        padding: 20px 24px;
        line-height: 1.4;
    }
    .eosb-print .header-table {
        width: 100%;
        margin-bottom: 18px;
        padding-bottom: 12px;
        border-bottom: 2px solid #1a5632;
    }
    .eosb-print .header-table td {
        vertical-align: middle;
    }
    .eosb-print .logo-cell {
        width: 120px;
        text-align: left;
    }
    .eosb-print .logo-cell img {
        max-height: 70px;
        max-width: 110px;
    }
    .eosb-print .title-cell {
        text-align: center;
    }
    .eosb-print .doc-title {
        font-size: 17px;
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: 1px;
        margin-bottom: 6px;
        color: #1a5632;
    }
    .eosb-print .company-line {
        font-size: 12px;
        color: #444;
        margin-bottom: 3px;
    }
    .eosb-print .law-line {
        font-size: 10px;
        color: #777;
        font-style: italic;
    }
    .eosb-print table {
        width: 100%;
        border-collapse: collapse;
        margin-bottom: 10px;
        page-break-inside: avoid;
    }
    .eosb-print .info-table {
        border: 1px solid #b0b8bf;
        margin-bottom: 16px;
        table-layout: fixed;
    }
    .eosb-print .info-table td {
        padding: 6px 10px;
        font-size: 11px;
        border: 1px solid #d5dbe0;
        vertical-align: middle;
        word-wrap: break-word;
    }
    .eosb-print .info-table td.field-label {
        background: #e8f5e9;
        font-weight: 600;
        color: #1a5632;
        width: 22%;
        font-size: 10px;
        text-transform: uppercase;
        letter-spacing: 0.3px;
    }
    .eosb-print .info-table td.field-value {
        width: 28%;
        color: #1a1a1a;
    }
    .eosb-print .section-table {
        margin-bottom: 12px;
        border: 1px solid #d5dbe0;
        table-layout: fixed;
    }
    .eosb-print .section-header td {
        background: #1a5632;
        color: #fff;
        padding: 7px 12px;
        font-size: 11px;
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: 0.6px;
    }
    .eosb-print .section-table td {
        padding: 6px 12px;
        border-bottom: 1px solid #ecf0f1;
        font-size: 11px;
    }
    .eosb-print .section-table td.label {
        width: 70%;
        color: #333;
    }
    .eosb-print .section-table td.value {
        width: 30%;
        text-align: right;
        font-family: 'Courier New', Consolas, monospace;
        font-size: 11px;
        color: #1a1a1a;
        white-space: nowrap;
    }
    .eosb-print .section-table tr:last-child td {
        border-bottom: none;
    }
    .eosb-print .highlight-row td {
        background: #e8f5e9;
        font-weight: 700;
        font-size: 11.5px;
        padding-top: 8px;
        padding-bottom: 8px;
    }
    .eosb-print .highlight-row td.label {
        color: #1a5632;
    }
    .eosb-print .highlight-row td.value {
        color: #1a5632;
    }
    .eosb-print .total-eosb-table {
        margin-top: 14px;
        margin-bottom: 18px;
        border: 2px solid #145a28;
    }
    .eosb-print .total-eosb-table td {
        background: #1a5632;
        color: #fff;
        padding: 14px 16px;
        font-size: 14px;
        font-weight: 700;
        letter-spacing: 0.5px;
    }
    .eosb-print .total-eosb-table td.value {
        text-align: right;
        font-family: 'Courier New', Consolas, monospace;
        font-size: 16px;
        white-space: nowrap;
    }
    .eosb-print .declaration {
        margin: 18px 0;
        padding: 12px 14px;
        border: 1px solid #bdc3c7;
        background: #fafbfc;
        font-size: 10px;
        line-height: 1.55;
        text-align: justify;
        color: #1a5632;
        border-radius: 3px;
    }
    .eosb-print .signatures {
        width: 100%;
        margin-top: 40px;
        page-break-inside: avoid;
    }
    .eosb-print .signatures td {
        width: 25%;
        text-align: center;
        padding-top: 36px;
        padding-bottom: 4px;
        border-top: 1px solid #1a5632;
        font-size: 10px;
        font-weight: 600;
        vertical-align: top;
        padding-left: 6px;
        padding-right: 6px;
    }
    .eosb-print .sig-name {
        display: block;
        margin-bottom: 3px;
        color: #1a5632;
        font-size: 11px;
    }
    .eosb-print .sig-role {
        display: block;
        font-weight: 400;
        color: #7f8c8d;
        font-size: 9px;
        text-transform: uppercase;
        letter-spacing: 0.5px;
    }
    .eosb-print .footer-meta {
        margin-top: 22px;
        font-size: 9px;
        color: #95a5a6;
        text-align: center;
        border-top: 1px solid #ecf0f1;
        padding-top: 8px;
    }
    .eosb-print .meta-divider {
        margin: 0 6px;
        color: #bdc3c7;
    }
</style>

<div class="eosb-print">

    {# ---- Header with Logo ---- #}
    <table class="header-table">
        <tr>
            <td class="logo-cell">
                {% if logo_url %}
                <img src="{{ logo_url }}" alt="Company Logo">
                {% endif %}
            </td>
            <td class="title-cell">
                <div class="doc-title">End of Service Benefit Calculation</div>
                <div class="company-line">{{ doc.company or '' }} &nbsp;|&nbsp; Kingdom of Saudi Arabia</div>
                <div class="law-line">As per Saudi Labor Law (Royal Decree No. M/51)</div>
            </td>
            <td style="width: 120px;"></td>
        </tr>
    </table>

    {# ---- Employee Information Table ---- #}
    <table class="info-table">
        <tr>
            <td class="field-label">Employee Name</td>
            <td class="field-value">{{ doc.employee_name or '-' }}</td>
            <td class="field-label">Employee ID</td>
            <td class="field-value">{{ doc.employee or '-' }}</td>
        </tr>
        <tr>
            <td class="field-label">Designation</td>
            <td class="field-value">{{ doc.designation or '-' }}</td>
            <td class="field-label">Department</td>
            <td class="field-value">{{ doc.department or '-' }}</td>
        </tr>
        <tr>
            <td class="field-label">Separation Type</td>
            <td class="field-value">{{ doc.separation_type or '-' }}</td>
            <td class="field-label">Nationality</td>
            <td class="field-value">{{ doc.nationality or '-' }}</td>
        </tr>
        <tr>
            <td class="field-label">Date of Joining</td>
            <td class="field-value">{{ frappe.utils.formatdate(doc.date_of_joining) if doc.date_of_joining else '-' }}</td>
            <td class="field-label">Date of Settlement</td>
            <td class="field-value">{{ frappe.utils.formatdate(doc.date_of_settlement) if doc.date_of_settlement else '-' }}</td>
        </tr>
        <tr>
            <td class="field-label">Iqama No</td>
            <td class="field-value">{{ doc.iqama_no or '-' }}</td>
            <td class="field-label">GOSI No</td>
            <td class="field-value">{{ doc.gosi_no or '-' }}</td>
        </tr>
        <tr>
            <td class="field-label">Passport Number</td>
            <td class="field-value">{{ doc.passport_number or '-' }}</td>
            <td class="field-label">Branch</td>
            <td class="field-value">{{ doc.branch or '-' }}</td>
        </tr>
    </table>

    {# ---- Service Summary ---- #}
    <table class="info-table">
        <tr>
            <td class="field-label">Employment Years</td>
            <td class="field-value">{{ "{:.4f}".format(doc.employment_years or 0) }}</td>
            <td class="field-label">Total Service Days</td>
            <td class="field-value">{{ doc.total_service_days or 0 }}</td>
        </tr>
        <tr>
            <td class="field-label">Number of Unpaid Leaves</td>
            <td class="field-value">{{ "{:.2f}".format(doc.unpaid_leaves_taken or 0) }}</td>
            <td class="field-label">Days Eligible for Gratuity</td>
            <td class="field-value">{{ doc.days_eligible_for_gratuity or doc.total_service_days or 0 }}</td>
        </tr>
    </table>

    {# ---- Salary As On Settlement Date ---- #}
    <table class="section-table">
        <tr class="section-header"><td colspan="2">Salary As On Settlement Date</td></tr>
        <tr><td class="label">Gross Salary (Full Monthly Wage)</td><td class="value">{{ "{:,.2f}".format(doc.gross_salary or 0) }} SAR</td></tr>
        <tr class="highlight-row"><td class="label">Daily Wage (Gross ÷ 30)</td><td class="value">{{ "{:,.2f}".format(doc.daily_wage or 0) }} SAR</td></tr>
    </table>

    {# ---- Gratuity (Saudi Labor Law) ---- #}
    <table class="section-table">
        <tr class="section-header"><td colspan="2">Gratuity Calculation (Saudi Labor Law)</td></tr>
        <tr><td class="label">Separation Type</td><td class="value" style="font-family: Arial, sans-serif;">{{ doc.separation_type or '-' }}</td></tr>
        {% if doc.termination_reason %}
        <tr><td class="label">Termination Reason</td><td class="value" style="font-family: Arial, sans-serif;">{{ doc.termination_reason }}</td></tr>
        {% endif %}
        <tr><td class="label">Gratuity Days (First 5 Years @ 15 days/year)</td><td class="value">{{ "{:.2f}".format(doc.gratuity_days_first_five_years or 0) }}</td></tr>
        <tr><td class="label">Gratuity Days (After 5 Years @ 30 days/year)</td><td class="value">{{ "{:.2f}".format(doc.gratuity_days_after_five_years or 0) }}</td></tr>
        <tr><td class="label">Total Gratuity Days</td><td class="value">{{ "{:.2f}".format(doc.total_gratuity_days or 0) }}</td></tr>
        <tr><td class="label">Gratuity Before Percentage</td><td class="value">{{ "{:,.2f}".format(doc.gratuity_before_percentage or 0) }} SAR</td></tr>
        <tr><td class="label">Gratuity Percentage Applied</td><td class="value">{{ "{:.2f}".format(doc.gratuity_percentage or 0) }}%</td></tr>
        <tr class="highlight-row"><td class="label">Gratuity Payable</td><td class="value">{{ "{:,.2f}".format(doc.gratuity_payable or 0) }} SAR</td></tr>
    </table>

    {# ---- Leave Encashment ---- #}
    <table class="section-table">
        <tr class="section-header"><td colspan="2">Leave Encashment</td></tr>
        <tr><td class="label">Leaves Accrued</td><td class="value">{{ "{:.2f}".format(doc.leaves_accrued or 0) }}</td></tr>
        <tr><td class="label">Leaves Utilized</td><td class="value">{{ "{:.2f}".format(doc.leaves_utilized or 0) }}</td></tr>
        <tr><td class="label">Leaves Balance</td><td class="value">{{ "{:.2f}".format(doc.leaves_balance or 0) }}</td></tr>
        <tr><td class="label">Leave Daily Rate</td><td class="value">{{ "{:,.2f}".format(doc.leave_daily_rate or 0) }} SAR</td></tr>
        <tr class="highlight-row"><td class="label">Leave Salary Payable</td><td class="value">{{ "{:,.2f}".format(doc.leave_salary_payable or 0) }} SAR</td></tr>
    </table>

    {# ---- Overtime Payment (only if relevant) ---- #}
    {% if doc.overtime_payable or doc.pending_overtime_hours %}
    <table class="section-table">
        <tr class="section-header"><td colspan="2">Overtime Payment</td></tr>
        <tr><td class="label">Pending Overtime Hours</td><td class="value">{{ "{:.2f}".format(doc.pending_overtime_hours or 0) }}</td></tr>
        <tr><td class="label">Overtime Rate Per Hour</td><td class="value">{{ "{:,.2f}".format(doc.overtime_rate_per_hour or 0) }} SAR</td></tr>
        {% if doc.overtime_notes %}
        <tr><td class="label">Notes</td><td class="value" style="font-family: Arial, sans-serif; font-size: 10px; white-space: normal;">{{ doc.overtime_notes }}</td></tr>
        {% endif %}
        <tr class="highlight-row"><td class="label">Overtime Payable</td><td class="value">{{ "{:,.2f}".format(doc.overtime_payable or 0) }} SAR</td></tr>
    </table>
    {% endif %}

    {# ---- Pending Salary & Allowances ---- #}
    <table class="section-table">
        <tr class="section-header"><td colspan="2">Pending Salary &amp; Allowances</td></tr>
        <tr><td class="label">Days Worked in Current Month</td><td class="value">{{ doc.days_worked_pending or 0 }}</td></tr>
        <tr><td class="label">Current Month Payment</td><td class="value">{{ "{:,.2f}".format(doc.current_month_payment or 0) }} SAR</td></tr>
        <tr><td class="label">Pending Salary Last Month</td><td class="value">{{ "{:,.2f}".format(doc.pending_salary_last_month or 0) }} SAR</td></tr>
        <tr><td class="label">Air Ticket Allowance</td><td class="value">{{ "{:,.2f}".format(doc.air_ticket_allowance or 0) }} SAR</td></tr>
        {% if doc.other_dues %}
        <tr><td class="label">Other Dues</td><td class="value">{{ "{:,.2f}".format(doc.other_dues or 0) }} SAR</td></tr>
        {% endif %}
        <tr class="highlight-row"><td class="label">Salary Payable</td><td class="value">{{ "{:,.2f}".format(doc.salary_payable or 0) }} SAR</td></tr>
    </table>

    {# ---- Recovery / Deductions ---- #}
    <table class="section-table">
        <tr class="section-header"><td colspan="2">Recovery / Deductions</td></tr>
        <tr><td class="label">Visa / Iqama Expense</td><td class="value">{{ "{:,.2f}".format(doc.visa_iqama_expense or 0) }} SAR</td></tr>
        <tr><td class="label">Loan / Advance Recovery</td><td class="value">{{ "{:,.2f}".format(doc.loan_advance_recovery or 0) }} SAR</td></tr>
        <tr><td class="label">Notice Period Shortfall</td><td class="value">{{ "{:,.2f}".format(doc.notice_period_shortfall or 0) }} SAR</td></tr>
        <tr><td class="label">Other Recovery</td><td class="value">{{ "{:,.2f}".format(doc.other_recovery or 0) }} SAR</td></tr>
        <tr class="highlight-row"><td class="label">Total Recovery</td><td class="value">{{ "{:,.2f}".format(doc.total_recovery or 0) }} SAR</td></tr>
    </table>

    {# ---- Final Total ---- #}
    <table class="total-eosb-table">
        <tr>
            <td class="label">TOTAL END OF SERVICE BENEFIT (SAR)</td>
            <td class="value">{{ "{:,.2f}".format(doc.net_payable or 0) }}</td>
        </tr>
    </table>

    {# ---- Declaration ---- #}
    <div class="declaration">
        {{ doc.acknowledgement_text or 'I confirm that I agree and accept the amount as calculated above as my full and final settlement as per Saudi Labor Law.' }}
    </div>

    {# ---- Signatures ---- #}
    <table class="signatures">
        <tr>
            <td>
                <span class="sig-name">{{ doc.employee_name or '' }}</span>
                <span class="sig-role">Employee</span>
            </td>
            <td>
                <span class="sig-name">&nbsp;</span>
                <span class="sig-role">HR Executive</span>
            </td>
            <td>
                <span class="sig-name">&nbsp;</span>
                <span class="sig-role">HR Manager</span>
            </td>
            <td>
                <span class="sig-name">&nbsp;</span>
                <span class="sig-role">Finance Manager</span>
            </td>
        </tr>
    </table>

    <div class="footer-meta">
        Document: <strong>{{ doc.name }}</strong>
        <span class="meta-divider">|</span>
        Status: <strong>{{ doc.status or 'Draft' }}</strong>
        <span class="meta-divider">|</span>
        Generated: <strong>{{ frappe.utils.formatdate(frappe.utils.nowdate()) }}</strong>
    </div>

</div>
